using Microsoft.Xna.Framework;
namespace StarlightSyndicateDemo;
internal static class ShipBatch23Tests
{
 public static void Run(){int checks=0;void Check(bool value,string label){if(!value)throw new Exception("BATCH23 FAIL: "+label);checks++;}
 Check(ShipBatch21.Battleships.Length==51&&FleetCatalog.Playable.Length==400,"exact batch scope");
 var world=new DemoWorld();world.NewGame(0);world.Credits=10000000;
 foreach(var profile in ShipBatch21.Battleships){var hull=FleetCatalog.ById[profile.ShipId];world.Screen=ViewMode.Station;world.Grid="station";world.SystemId=profile.HomeSystem;float before=world.Credits;
 Check(world.BoardFleetHull(hull.Id),"acquire "+hull.Name);var ship=world.Player;Check(world.Credits==before-(profile.Starter||profile.LegacyCharter?0:(float)profile.Price),"exact acquisition price "+hull.Name);
 Check(hull.Attributes.Where(a=>ShipAttributeCatalog.ByKey.ContainsKey(a.Key)&&a.Key is not ("cpuLoad" or "powerLoad")).All(a=>Math.Abs((ship.Attributes.GetValueOrDefault(a.Key)??0)-a.Value)<.001),"source attributes unmodified "+hull.Name+" / "+string.Join(",",hull.Attributes.Where(a=>ShipAttributeCatalog.ByKey.ContainsKey(a.Key)&&a.Key is not ("cpuLoad" or "powerLoad")&&Math.Abs((ship.Attributes.GetValueOrDefault(a.Key)??0)-a.Value)>.001).Select(a=>a.Key+":"+a.Value+"/"+ship.Attributes.GetValueOrDefault(a.Key))));
 Check(world.TotalFitCpu<=ship.Stat("cpuOutput")+.001&&world.TotalFitPower<=ship.Stat("powerOutput")+.001,"legal budget "+hull.Name);
 foreach(string slot in new[]{"high","medium","low"})Check(FittingLayoutModel.Installed(ship).Count(m=>m.Bank==slot)<=ship.Stat(slot=="high"?"hiSlots":slot=="medium"?"medSlots":"lowSlots"),"shared sockets "+hull.Name+" "+slot);
 Check(ship.Weapons.Where(w=>w.ModuleId.Length>0).All(w=>w.Definition!.Size==profile.WeaponSize),"correct weapon scale "+hull.Name);
 if(hull.Class=="Battleship")Check(ship.Weapons.Count(w=>w.ModuleId.Length>0)>0,"large attack rack "+hull.Name);
 Check(world.CargoUsed<=ship.CargoMax+.001,"real spare cargo "+hull.Name);Check(ship.TotalDps>0&&double.IsFinite(ship.EffectiveHitpoints),"finite offensive and defensive stats "+hull.Name);
 Check(ship.Drones.Sum(d=>d.Definition.Volume)<=ship.Stat("droneCapacity")&&ship.Drones.Sum(d=>d.Definition.Bandwidth)<=ship.Stat("droneBandwidth"),"bay and bandwidth "+hull.Name);
 if(profile.Starter)Check(ship.Utilities.Any(s=>s.Definition?.Harvest==true),"starter mining "+hull.Name);
 if(profile.Role=="Exploration")Check(ship.Utilities.Any(s=>s.Definition?.Kind=="CoreProbe")&&ship.Utilities.Any(s=>s.Definition?.Kind=="Data")&&ship.Utilities.Any(s=>s.Definition?.Kind=="Relic"),"exploration mission equipment "+hull.Name);
 if(profile.Role=="Logistics")Check(ship.Support.Any(s=>s.Definition?.Repair==true),"remote repair "+hull.Name);
 if(profile.Role=="Electronic warfare")Check(ship.Ewar.Any(s=>s.Definition!=null),"EW mission equipment "+hull.Name);
 world.EnterGrid("belt");var target=world.Targets.First(t=>t.Kind==TargetKind.Raider);target.Position=ship.Position+new Vector3(1200,0,0);target.Velocity=Vector3.Zero;target.Profile!.SetStat("shieldCapacity",100000);target.Profile.SetStat("armorHP",100000);target.Profile.SetStat("hp",100000);target.Shield=target.Armor=target.Hull=100000;world.SelectedId=world.LockedId=target.Id;world.ToggleFleetRack();for(int i=0;i<180;i++)world.Update(1f/30);Check(target.Shield+target.Armor+target.Hull<300000,"live weapon damage "+hull.Name);
 if(profile.Role=="Logistics"){
 target.Friendly=true;target.Position=ship.Position+new Vector3(500,0,0);target.Shield=target.Armor=1;target.Cap=1;int rep=Array.FindIndex(ship.Support,q=>q.Definition?.Repair==true);Check(rep>=0&&world.ToggleSupport(rep),"activate cruiser logistics "+hull.Name);for(int i=0;i<400;i++)world.UpdateSupport(.05f);Check(target.Shield>1||target.Armor>1,"cruiser repair lands "+hull.Name);
 int transfer=Array.FindIndex(ship.Support,q=>q.Definition?.Kind=="Cap");if(transfer>=0){ship.Cap=ship.MaxCap;float capBefore=target.Cap;Check(world.ToggleSupport(transfer),"activate cruiser energy transfer "+hull.Name);world.UpdateSupport(.05f);Check(target.Cap>capBefore,"cruiser energy transfer lands "+hull.Name);}
 }
 if(profile.Effects.Any(e=>e.System=="ewar"&&e.Filter=="Neutralizer")){Check(ship.Ewar[0].Definition?.Kind==EwarKind.Neutralizer&&ship.Ewar[0].Definition!.Size==3,"large energy warfare starter fit "+hull.Name);target.Cap=10000;target.Profile!.SetStat("capacitorCapacity",20000);float beforeCap=target.Cap;world.ToggleEwar(0);world.Update(.05f);Check(target.Cap<beforeCap,"live battleship neutralizer drains target "+hull.Name);}
 if(profile.Role=="Electronic warfare"){target.Profile!.NativeSensor=ship.Ewar[1].Definition!.Sensor;foreach(string key in new[]{"scanRadarStrength","scanGravimetricStrength","scanMagnetometricStrength","scanLadarStrength"})target.Profile.SetStat(key,.01);world.ToggleEwar(1);world.Update(.05f);Check(world.EwarFor(target.Id).Jammers.Contains("player"),"battleship ECM applies real jam "+hull.Name);}
 Check(ship.Mobility.Any(m=>m.Definition?.Kind=="AB"&&m.Definition.Size==3),"battleship propulsion starter fit "+hull.Name);
 Check(ship.Defense.Any(d=>d.Definition?.Size==3&&d.Definition.Kind is "ArmorRepair" or "ShieldBoost"),"large local repair "+hull.Name);
 Console.WriteLine("BATCH23 PASS: "+hull.Name+" / "+profile.Role);
 }
 world.Screen=ViewMode.Station;world.Grid="station";
 Ship Hull(string name,int level=1){var ship=new Ship();ship.ApplyFleetHull(FleetCatalog.Source(name));ship.Defense=Enumerable.Range(0,12).Select(_=>new DefenseState()).ToArray();foreach(int skill in ShipBatch21.ById[ship.CombatHull].Traits.Where(t=>t.Skill!=0).Select(t=>t.Skill).Distinct())ship.HullProficiency[skill]=level;return ship;}
 bool Near(double a,double b)=>Math.Abs(a-b)<.001;
 var plate=DefenseCatalog.All.First(d=>d.Kind=="Plate"&&d.Size==3);var extender=DefenseCatalog.All.First(d=>d.Kind=="Extender"&&d.Size==3);var bulkhead=DefenseCatalog.All.First(d=>d.Kind=="Bulkhead");
 foreach(var p in ShipBatch21.Battleships){var h=FleetCatalog.ById[p.ShipId];var bare=Hull(h.SourceHull);double baseArmor=bare.MaxArmor,baseShield=bare.MaxShield,baseStructure=bare.MaxHull;
 bare.Defense[6]=DefenseState.Create(plate.Id);double plateScale=p.Effects.Any(e=>e.System=="tank"&&e.Key=="plate")?1.5:1;Check(Near(bare.MaxArmor,baseArmor+plate.Bonuses["armorHPBonusAdd"]*plateScale),"role plate adds only module HP "+h.Name);bare.Defense[6]=new();
 bare.Defense[1]=DefenseState.Create(extender.Id);double extScale=p.Effects.Any(e=>e.System=="tank"&&e.Key=="extender")?2:1;Check(Near(bare.MaxShield,baseShield+extender.Bonuses["shieldBonus"]*extScale),"role extender adds only module HP "+h.Name);bare.Defense[1]=new();
 bare.Defense[6]=DefenseState.Create(bulkhead.Id);double extra=p.Effects.Any(e=>e.System=="tank"&&e.Key=="bulkhead")?.05:0;Check(Near(bare.MaxHull,baseStructure*(bulkhead.Bonuses["structureHPMultiplier"]+extra)),"additional bulkhead modifier is additive "+h.Name);bare.Defense[6]=new();Check(Near(bare.MaxHull,baseStructure)&&Near(bare.MaxArmor,baseArmor)&&Near(bare.MaxShield,baseShield),"unfit restores bare source tank "+h.Name);
 }
 var largeRail=WeaponCatalog.All.First(w=>w.Family=="Railguns"&&w.Size==3);var mediumRail=WeaponCatalog.All.First(w=>w.Family=="Railguns"&&w.Size==2);var mega=Hull("Megathron",5);Check(Near(mega.HullWeapon(largeRail,"cycle"),.75)&&Near(mega.HullWeapon(largeRail,"tracking"),1.375)&&mega.HullWeapon(mediumRail,"cycle")==1,"large hybrid bonuses and size isolation");
 var drone=DroneCatalog.All.First(d=>!d.Fighter&&d.Kind=="Sentry"&&d.Optimal>0);var dom=drone.Enhanced(Hull("Dominix",5));Check(Near(dom.Optimal/drone.Optimal,1.375)&&Near(dom.Tracking/drone.Tracking,1.375)&&Near(dom.Packet.Total/drone.Packet.Total,1.5)&&Near(dom.Shield/drone.Shield,1.5),"battleship drone optimal, tracking, damage and HP");
 var cruise=WeaponCatalog.All.First(w=>w.Family=="Missile Launcher Cruise"&&w.Size==3);var raven=Hull("Raven",5);Check(Near(raven.HullWeapon(cruise,"cycle"),.75)&&Near(raven.HullWeapon(cruise,"missileVelocity"),1.5),"cruise missile cadence and velocity");Check(Near(Hull("Raven Navy Issue",5).HullWeapon(cruise,"explosionRadius"),.75),"navy cruise missile explosion radius reduction");
 var laser=WeaponCatalog.All.First(w=>w.Family=="Pulse lasers"&&w.Size==3);var apoc=Hull("Apocalypse",5);Check(Near(apoc.HullWeapon(laser,"optimal"),1.5)&&Near(apoc.HullWeapon(laser,"damage"),1.25)&&Near(apoc.HullWeapon(laser,"cap"),.5),"large laser reach, damage and capacitor");Check(Near(Hull("Apocalypse Imperial Issue",5).MaxCap/FleetCatalog.Source("Apocalypse Imperial Issue").Value("capacitorCapacity"),1.25),"imperial capacitor capacity");
 var artillery=WeaponCatalog.All.First(w=>w.Family=="Artillery"&&w.Size==3);var storm=Hull("Maelstrom",5);Check(Near(storm.HullWeapon(artillery,"damage"),1.5)&&Near(storm.RigLocalAmount("ShieldBoost"),1.5),"projectile damage and local shield boost");Check(Near(Hull("Typhoon",5).HullWeapon(cruise,"explosionVelocity"),1.375),"missile application velocity");
 var neut=EwarCatalog.All.First(e=>e.Kind==EwarKind.Neutralizer&&e.Size==3);var geddon=Hull("Armageddon",5).HullEwar(neut)!;Check(Near(geddon.Optimal/neut.Optimal,1.5)&&Near(geddon.Falloff/neut.Falloff,1.25),"battleship energy warfare optimal and falloff");
 var ecm=EwarCatalog.All.First(e=>e.Kind==EwarKind.ECM);var burst=EwarCatalog.All.First(e=>e.Kind==EwarKind.BurstJam);var scorp=Hull("Scorpion",5);Check(Near(scorp.HullEwar(ecm)!.Strength/ecm.Strength,1.75)&&Near(scorp.HullEwar(ecm)!.Optimal/ecm.Optimal,2.25)&&Near(scorp.HullEwar(burst)!.Strength/burst.Strength,1.75)&&Near(scorp.HullEwar(burst)!.Radius/burst.Radius,2.25),"targeted and burst ECM strength and reach");
 var paid=ShipBatch21.Battleships.First();var reject=new DemoWorld();reject.NewGame(0);reject.SystemId=paid.HomeSystem;reject.Credits=0;Check(!reject.BoardFleetHull(paid.ShipId)&&reject.FleetBerths.Count==0&&reject.Credits==0,"insufficient funds atomic");reject.Credits=500000;reject.SystemId=paid.HomeSystem=="aster"?"vale":"aster";Check(!reject.BoardFleetHull(paid.ShipId)&&reject.Credits==500000&&reject.FleetBerths.Count==0,"wrong station atomic");
 var buy=new DemoWorld();buy.NewGame(0);buy.SystemId=paid.HomeSystem;buy.Credits=500000;var active=buy.Player;Check(buy.BuyAdditionalFleetHull(paid.ShipId)&&ReferenceEquals(buy.Player,active)&&buy.Credits==500000-(float)paid.Price&&buy.FleetBerths.Count==1,"additional purchase preserves active ship and exact wallet");Check(buy.BoardFleetBerth(0)&&buy.Player.CombatHull==paid.ShipId,"board fitted battleship berth");
 int trainingSkill=paid.Traits.First(t=>t.Skill!=0).Skill;float fraction=buy.Player.Armor/buy.Player.MaxArmor;Check(buy.TrainHullProficiency(trainingSkill)&&buy.Player.HullProficiency[trainingSkill]==2&&Near(buy.Player.Armor/buy.Player.MaxArmor,fraction),"battleship training pays and preserves damage fraction");
 var forbidden=WeaponCatalog.All.First(w=>w.Size==4) with{Role=""};Check(buy.FitError(forbidden,0).Contains("fitting class"),"capital weapon rejected on basic battleship");
 string temp=Path.Combine(Path.GetTempPath(),"batch23-"+Guid.NewGuid());var prior=Environment.GetEnvironmentVariable("STARLIGHT_SAVE_DIR");try{Environment.SetEnvironmentVariable("STARLIGHT_SAVE_DIR",temp);world.Save();var loaded=new DemoWorld();Check(loaded.Load()&&loaded.GrantedFleetHulls.Count==51&&loaded.FleetBerths.Count==world.FleetBerths.Count,"all 51 battleships persist");Check(loaded.Player.CombatHull==world.Player.CombatHull,"active battleship persisted");foreach(var berth in world.FleetBerths){var copy=loaded.FleetBerths.Single(b=>b.System==berth.System&&b.Ship.CombatHull==berth.Ship.CombatHull);Check(copy.Ship.Attributes.SequenceEqual(berth.Ship.Attributes)&&copy.Ship.Weapons.Select(w=>w.ModuleId).SequenceEqual(berth.Ship.Weapons.Select(w=>w.ModuleId)),"parked battleship source stats and rack persisted "+berth.Ship.HullName);}}finally{Environment.SetEnvironmentVariable("STARLIGHT_SAVE_DIR",prior);if(Directory.Exists(temp))Directory.Delete(temp,true);}
 Console.WriteLine(checks+" batch23 checks passed / all 51 hulls.");
 }
}
